                     tmp25630 = -tmp25629
                     tmp25631 = tmp25628 + tmp25630
                     tmp25632 = tmp25631*tmp24290
                     tmp24411 = tmp25627 + tmp25632
                  end if
                  tmp25633 = tmp24411*state%s45(i)
                  tmp24280 = tmp24280 + tmp25633
               end if
            end do
            tmp24277(j) = tmp24277(j) + tmp24280
         end do
         !$omp end do
         deallocate (tmp24279)
         !$omp end parallel
      end block
      call gemv(state%s19, tmp2825, tmp25634, trans="t")
      hvp_vn = tmp24277 + tmp25634
   end subroutine nonlocal_pcm_tangent_one

   module subroutine nonlocal_pcm_response(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call nonlocal_pcm_mf_response(state, dv, dvn, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[nonlocal_pcm_response] call nonlocal_pcm_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_response] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call nonlocal_pcm_response_one(state, dv(:, blk), dvn(:, blk), hvp_v(:, blk), &
                                        hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine nonlocal_pcm_response

   !> One direction of nonlocal_pcm_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_response_one(state, dv, dvn, hvp_v, hvp_vn, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp13(:), tmp14(:), tmp15(:), tmp16(:), &
                               tmp17(:), tmp18(:), tmp19(:), tmp22(:), tmp23(:), tmp24(:), &
                               tmp25(:), tmp26(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), &
                               tmp31(:), tmp32(:)
      real(wp), allocatable :: tmp11(:), tmp12(:), tmp20(:), tmp21(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt])) then
         call fatal_error(error, "[nonlocal_pcm_response_one] hvp_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat == 0) allocate (tmp17(npt), stat=stat)
      if (stat == 0) allocate (tmp18(npt), stat=stat)
      if (stat == 0) allocate (tmp19(npt), stat=stat)
      if (stat == 0) allocate (tmp22(npt), stat=stat)
      if (stat == 0) allocate (tmp23(npt), stat=stat)
      if (stat == 0) allocate (tmp24(npt), stat=stat)
      if (stat == 0) allocate (tmp25(npt), stat=stat)
      if (stat == 0) allocate (tmp26(npt), stat=stat)
      if (stat == 0) allocate (tmp27(npt), stat=stat)
      if (stat == 0) allocate (tmp28(npt), stat=stat)
      if (stat == 0) allocate (tmp29(npt), stat=stat)
      if (stat == 0) allocate (tmp30(npt), stat=stat)
      if (stat == 0) allocate (tmp31(npt), stat=stat)
      if (stat == 0) allocate (tmp32(npt), stat=stat)
      if (stat == 0) allocate (tmp11(3*npt), stat=stat)
      if (stat == 0) allocate (tmp12(3*npt), stat=stat)
      if (stat == 0) allocate (tmp20(3*npt), stat=stat)
      if (stat == 0) allocate (tmp21(3*npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[nonlocal_pcm_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%c1 => state%s14
      state%op1%c2 => state%s15
      state%op1%c4 => state%s19
      state%op1%c6 => state%s10
      state%op2%points => state%r
      state%op2%c1 => state%s10
      call gemv(state%s14, dv, tmp1)
      tmp2 = state%s23*tmp1
      call gemv(state%s19, dvn, tmp3)
      tmp4 = state%s25*tmp3
      tmp5 = tmp2 + tmp4
      call gemv(state%s15, dv, tmp6)
      tmp7 = (-6.283185307179586_wp)*dv
      tmp8 = tmp6 + tmp7
      tmp9 = state%s28*tmp8
      tmp10 = tmp5 + tmp9
      tmp11(1:npt) = tmp10
      tmp11(npt + 1:2*npt) = 0.0_wp
      tmp11(2*npt + 1:3*npt) = tmp9
      tmp12 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp11, tmp12, error)
      if (allocated(error)) return
      tmp13 = tmp12(1:npt)
      tmp14 = 0.0_wp
      call state%solver%solve(state%op2, .false., tmp13, tmp14, error)
      if (allocated(error)) return
      tmp15 = state%a*tmp14
      tmp16 = state%s35*tmp15
      tmp17 = state%s35*dv
      tmp18 = tmp17*state%a
      tmp19 = 0.0_wp
      call state%solver%solve(state%op2, .true., tmp18, tmp19, error)
      if (allocated(error)) return
      tmp20(1:npt) = tmp19
      tmp20(npt + 1:2*npt) = 0.0_wp
      tmp20(2*npt + 1:3*npt) = 0.0_wp
      tmp21 = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp20, tmp21, error)
      if (allocated(error)) return
      tmp22 = tmp21(2*npt + 1:3*npt)
      tmp23 = tmp21(1:npt)
      tmp24 = tmp22 + tmp23
      tmp25 = state%s36*tmp24
      tmp26 = tmp16 + tmp25
      tmp27 = state%s28*tmp24
      call gemv(state%s15, tmp27, tmp28, trans="t")
      tmp29 = tmp26 + tmp28
      tmp30 = state%s23*tmp23
      call gemv(state%s14, tmp30, tmp31, trans="t")
      hvp_v = tmp29 + tmp31
      tmp32 = state%s25*tmp23
      call gemv(state%s19, tmp32, hvp_vn, trans="t")
   end subroutine nonlocal_pcm_response_one

end submodule pcmgen_gauss_nonlocal_tangent
